<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-vial text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">pH pOH Calculator</h5><p class="text-muted small mb-0">Full pH/pOH/[H⁺]/[OH⁻] interconversion</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Input Type</label><select id="in-mode" class="form-select form-select-lg"><option value="ph">pH</option><option value="poh">pOH</option><option value="h">[H⁺] mol/L</option><option value="oh">[OH⁻] mol/L</option></select></div><div class="col-md-6"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Value</label><input type="number" id="in-v" class="form-control form-control-lg" value="7" step="any"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Relations:</b> pH+pOH=14 | pH=−log[H⁺] | pOH=−log[OH⁻]</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var m=document.getElementById("in-mode").value,v=parseFloat(document.getElementById("in-v").value),ph,poh,h,oh;if(isNaN(v))return;if(m==="ph"){ph=v;poh=14-v;h=Math.pow(10,-v);oh=Math.pow(10,-poh);}else if(m==="poh"){poh=v;ph=14-v;h=Math.pow(10,-ph);oh=Math.pow(10,-v);}else if(m==="h"){h=v;ph=-Math.log10(v);poh=14-ph;oh=Math.pow(10,-poh);}else{oh=v;poh=-Math.log10(v);ph=14-poh;h=Math.pow(10,-ph);}document.getElementById("out-main").textContent="pH "+ph.toFixed(2)+" | pOH "+poh.toFixed(2);document.getElementById("out-main").style.fontSize="1.8rem";document.getElementById("out-unit").textContent="";document.getElementById("out-detail").innerHTML='<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">pH</div><div class="h5 fw-bold mb-0 text-primary">'+ph.toFixed(4)+'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">pOH</div><div class="h5 fw-bold mb-0 text-info">'+poh.toFixed(4)+'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">[H⁺]</div><div class="h5 fw-bold mb-0 text-danger">'+h.toExponential(2)+'</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">[OH⁻]</div><div class="h5 fw-bold mb-0 text-success">'+oh.toExponential(2)+'</div></div></div>';var nat=ph<6.5?"Acidic":ph>7.5?"Basic":"Neutral";document.getElementById("out-ins").innerHTML="<p>Solution is <b>"+nat+"</b>. Kw = [H⁺]×[OH⁻] = "+(h*oh).toExponential(2)+"</p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-v").value=7;document.getElementById("in-mode").value="ph";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\ph-poh-calculator.blade.php ENDPATH**/ ?>